/** WS-VAL-FEC PIC 99: primer dígito = opción, segundo = días hacia atrás. */
public record SolicitudFecha(int opcion, int diasAtras) {
    public static SolicitudFecha de(String valFec) {                 // "00".."99"
        return new SolicitudFecha(valFec.charAt(0) - '0', valFec.charAt(1) - '0');
    }
}

/** WKS-PARAM100 PIC 9(10): fecha AAAAMMDD (o dato) y nodo de dos dígitos. */
public record RespuestaFecha(long valor8, int nodo) {
    public static RespuestaFecha de(LocalDate f, int nodo) {
        return new RespuestaFecha(Long.parseLong(f.format(DateTimeFormatter.BASIC_ISO_DATE)), nodo);
    }
    public static RespuestaFecha soloNodo(int nodo) { return new RespuestaFecha(0, nodo); }
    public long comoTaskValue() { return valor8 * 100 + nodo; }   // SET MYSELF (TASKVALUE) TO WKS-PARAM100
}

/** WS-TABLA-NUM-DIAS: "312831303130" + "313130313031", 12 ocurrencias PIC 9(02). */
static final int[] DIAS_POR_MES = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

@Component
@RequiredArgsConstructor
public class FechaProcesoTasklet implements Tasklet {      // 00000000-PRINCIPAL

    private final FechaProcesoService servicio;
    private final P100Properties props;                    // ambiente-desarrollo: ACYPBETA

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var solicitud = SolicitudFecha.de(parametro(ctx, "valFec"));
        if (!props.esDesarrollo()) {
            servicio.validaVersion("S500P100", "25MTP007");     // 20000050-CHECO-VER
        }
        RespuestaFecha r = servicio.resuelve(solicitud);         // 20001000-ABRO-BASE + 20002000-FECHA-PRO
        c.getStepExecution().getExecutionContext().putLong("taskValue", r.comoTaskValue());
        c.setExitStatus(new ExitStatus("FECHA_" + r.valor8()));
        return RepeatStatus.FINISHED;
    }
}

/** 20000050-CHECO-VER. */
public void validaVersion(String id, String version) {
    if (versiones.compara(id, version) < 0) {                  // S000-CTR-CVEERROR < 0
        throw new VersionNoVigenteException("VER. EJECUTADA DIF. A VERSIONES");
    }                                                          // CHANGE ATTRIBUTE STATUS OF MYSELF TO -1
}

/** 20001000-ABRO-BASE: solo la opción 3 con cero días va a Tarjetas. */
@Transactional(readOnly = true)                               // OPEN INQUIRY
public RespuestaFecha resuelve(SolicitudFecha s) {
    return (s.opcion() == 3 && s.diasAtras() == 0)
            ? desdeTarjetas()                                  // S500BD04TARJETAS / B01PCONTROL
            : desdeCaptacion(s);                               // S500BD01CAPTACION / B02CONTROL
}

/** 20002010-FECHA-BD01: primera mitad de la tabla de opciones. */
private RespuestaFecha desdeCaptacion(SolicitudFecha s) {
    ControlCaptacion b02 = control.find()
            .orElseThrow(() -> new ProcesoAbortadoException("ERROR REG. DE CONTROL VACIO"));   // DMTERMINATE
    int op = s.opcion(), d = s.diasAtras();

    if (op == 3 && d == 1) {                                  // opción "31": solo el nodo activo
        return RespuestaFecha.soloNodo(b02.usoFuturo05());
    }
    if (op > 0 && d > 0) {                                    // inválida: fecha de línea sin proyectar
        return RespuestaFecha.de(b02.fechaLinea(), b02.numCsi());
        // la condición (op == 3 && d > 1) del fuente ya está contenida en esta
    }
    if (op == 0 && d > 0) {                                   // "01".."09": d días hacia atrás
        return proyecta(b02, s);
    }
    return segundaMitad(b02, s);                              // opciones 9, 5, 6, 7, 8, 1, 2, 4 y 0
}

/** Segunda mitad de 20002010-FECHA-BD01. */
private RespuestaFecha segundaMitad(ControlCaptacion b02, SolicitudFecha s) {
    return switch (s.opcion()) {
        case 9 -> new RespuestaFecha(b02.actTeleton(), b02.numCsi());   // indicador Teletón en el campo de fecha
        case 5 -> {
            LocalDate tecleada = consola.pideFechaValida();             // 20002100-PIDO-FECHA UNTIL WS-1VEZ = 1
            proyecta(b02, s);                                           // el fuente llama a LOCSUP aunque descarte el resultado
            yield RespuestaFecha.de(tecleada, b02.numCsi());
        }
        case 6 -> RespuestaFecha.de(ultimoDiaMesAnterior(b02.fechaLinea()), b02.numCsi());
        case 7 -> RespuestaFecha.de(b02.fechaLinea().withDayOfMonth(1), b02.numCsi());
        case 8 -> RespuestaFecha.de(b02.fechaLinea(), b02.numCsi());
        case 1, 2, 4 -> proyecta(b02, s);
        default -> proyecta(b02, s);                                    // opción 0 sin días
    };
}

/** 20002200-PROY-FEC + 40000000-CALL-FECPRO. */
private RespuestaFecha proyecta(ControlCaptacion b02, SolicitudFecha s) {
    int dias = (s.diasAtras() > 0) ? s.diasAtras()
             : (s.opcion() == 1)   ? 1
             : 2;                                               // opciones 0, 2, 4 y 5
    LocalDate fecha = calendario.retrocede(b02.fechaLinea(), dias)   // LOCSUP función 15, formato 12
            .orElseThrow(() -> new ProcesoAbortadoException("ERROR AL ACCESAR LOCSUP"));
    return RespuestaFecha.de(fecha, b02.numCsi());
}

/** 20002300-FEC-ULTDIAMES, con la regla de bisiesto del fuente. */
static LocalDate ultimoDiaMesAnterior(LocalDate fechaLinea) {
    int anio = fechaLinea.getYear(), mes = fechaLinea.getMonthValue();
    if (mes == 1) { mes = 12; anio -= 1; } else { mes -= 1; }
    int dia = DIAS_POR_MES[mes - 1];
    if (mes == 2 && anio % 4 == 0) {
        dia = 29;                       // el fuente no aplica la excepción de 100 y 400
    }
    return LocalDate.of(anio, mes, dia);
    // Equivalente gregoriano exacto: fechaLinea.withDayOfMonth(1).minusDays(1).
    // Coinciden en todos los años de 1901 a 2099; difieren en 2100.
}

@Component
@RequiredArgsConstructor
public class ConsolaOperador {                      // 20002100-PIDO-FECHA (ACCEPT FECHA)

    private final OperadorPrompt prompt;            // sustituye ACCEPT / DISPLAY de consola MCP

    public LocalDate pideFechaValida() {
        while (true) {
            String txt = prompt.pide("DAME FECHA DE PROCESO, FORMATO AAAAMMDD");
            try {
                LocalDate f = LocalDate.parse(txt, DateTimeFormatter.BASIC_ISO_DATE);
                if (f.getYear() >= 1989 && f.getYear() <= 2999) return f;   // ANOOK
            } catch (DateTimeParseException e) {
                // cae al mensaje de error
            }
            prompt.avisa("LA FECHA ESTA MAL TECLEADA");
        }
    }
}

/** 20002500-FECHA-BD04. */
private RespuestaFecha desdeTarjetas() {
    ControlTarjetas b01p = controlTarjetas.findFirst()          // 90400001-B01PCONTROL-FINDF
            .orElseThrow(() -> new ProcesoAbortadoException("NO HAY B01PCONTROL EN BD04 "));
    return new RespuestaFecha(b01p.ultimoArchivoAplicado(), b01p.numCsi());   // B01P-ULT-ARCHAPLI
}
